SELECT p.risk_tolerance, COUNT(DISTINCT p.investor_id) AS investor_count
FROM ATOM_ENTITY_INVESTOR_PROFILE_001 p
WHERE EXISTS (
    SELECT 1 FROM ATOM_ENTITY_PORTFOLIO_HOLDING_001 o
    WHERE o.investor_id = p.investor_id AND o.investment_type = 'Equity'
) AND EXISTS (
    SELECT 1 FROM ATOM_EVENT_CASH_FLOW_001 c
    WHERE c.investor_id = p.investor_id AND c.type = 'SIP'
)
GROUP BY p.risk_tolerance;

